import re

def extract_error_windows(details,max_hits=3):
    t=(details or '').replace('\ufeff','').replace('\xef\xbb\xbf','')
    t=re.sub(r'\x1b\[[0-9;]*m','',t)
    keys=('##[error]','FAIL','AssertionError','Error:','exit code','Traceback','ImportError')
    lines=t.splitlines(); hits=[]
    for i,l in enumerate(lines):
        if any(k in l for k in keys):
            hits.append('\n'.join(lines[max(0,i-5):min(len(lines),i+15)]))
            if len(hits)>=max_hits: break
    return '\n---\n'.join(hits)
